arguments.command:
mkdir -p /workspace/submission/infra && cd /workspace/submission/infra
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

variable "config_path" {
  description = "Path to the deployment inputs file"
  type        = string
  default     = "/workspace/config/config.json"
}

locals {
  cfg      = jsondecode(file(var.config_path))
  prefix   = local.cfg.resource_prefix
  region   = local.cfg.region
  endpoint = local.cfg.aws_endpoint_url
  azs      = ["${local.region}a", "${local.region}b"]
  tags     = { ClearLedgerDeployment = local.prefix }

  db_password = sensitive(local.cfg.db_password)
}

provider "aws" {
  region     = local.region
  access_key = "test"
  secret_key = "test"

  skip_credentials_validation = true
  skip_metadata_api_check     = true
  skip_requesting_account_id  = true
  skip_region_validation      = true
  s3_use_path_style           = true

  endpoints {
    ec2              = local.endpoint
    elbv2            = local.endpoint
    ecs              = local.endpoint
    rds              = local.endpoint
    dynamodb         = local.endpoint
    elasticache      = local.endpoint
    s3               = local.endpoint
    sqs              = local.endpoint
    lambda           = local.endpoint
    scheduler        = local.endpoint
    cognitoidp       = local.endpoint
    iam              = local.endpoint
    kms              = local.endpoint
    cloudwatchlogs   = local.endpoint
    sts              = local.endpoint
  }
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
}
EOF
cat > network.tf <<'EOF'
resource "aws_vpc" "main" {
  cidr_block           = "10.42.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = merge(local.tags, { Name = "${local.prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.prefix}-igw" })
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.azs[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = true
  tags                    = merge(local.tags, { Name = "${local.prefix}-public-${count.index}" })
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.azs[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  map_public_ip_on_launch = false
  tags                    = merge(local.tags, { Name = "${local.prefix}-private-${count.index}" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.prefix}-public-rt" })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.prefix}-private-rt" })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security groups. Rules are declared inline so that Terraform is authoritative
# over them (out-of-band rules are removed on the next apply as well as by deploy.sh).
resource "aws_security_group" "alb" {
  name        = "${local.prefix}-alb"
  description = "ClearLedger ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "API port inside the VPC only"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.tags, { Name = "${local.prefix}-alb" })
}

resource "aws_security_group" "ecs" {
  name        = "${local.prefix}-ecs"
  description = "ClearLedger API tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "API port from the ALB"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "AWS control plane (HTTPS)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "AWS control plane (local endpoint)"
    from_port   = 4566
    to_port     = 4566
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "PostgreSQL"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Valkey"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.tags, { Name = "${local.prefix}-ecs" })
}

resource "aws_security_group" "rds" {
  name        = "${local.prefix}-rds"
  description = "ClearLedger PostgreSQL"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from API tasks"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress = []

  tags = merge(local.tags, { Name = "${local.prefix}-rds" })
}

resource "aws_security_group" "valkey" {
  name        = "${local.prefix}-valkey"
  description = "ClearLedger Valkey"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Valkey from API tasks"
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress = []

  tags = merge(local.tags, { Name = "${local.prefix}-valkey" })
}
EOF
cat > kms.tf <<'EOF'
locals {
  kms_purposes = toset(["database", "messaging", "projection", "audit"])
}

resource "aws_kms_key" "this" {
  for_each                = local.kms_purposes
  description             = "ClearLedger ${each.key} key (${local.prefix})"
  enable_key_rotation     = true
  deletion_window_in_days = 10
  tags                    = merge(local.tags, { Name = "${local.prefix}-${each.key}" })
}

resource "aws_kms_alias" "this" {
  for_each      = local.kms_purposes
  name          = "alias/${local.prefix}-${each.key}"
  target_key_id = aws_kms_key.this[each.key].key_id
}
EOF
cat > logs.tf <<'EOF'
resource "aws_cloudwatch_log_group" "api" {
  name              = "/clearledger/${local.prefix}/api"
  retention_in_days = 14
  tags              = local.tags
}

resource "aws_cloudwatch_log_group" "projector" {
  name              = "/clearledger/${local.prefix}/projector"
  retention_in_days = 14
  tags              = local.tags
}

resource "aws_cloudwatch_log_group" "relay" {
  name              = "/clearledger/${local.prefix}/outbox-relay"
  retention_in_days = 14
  tags              = local.tags
}

resource "aws_cloudwatch_log_group" "archiver" {
  name              = "/clearledger/${local.prefix}/audit-archiver"
  retention_in_days = 14
  tags              = local.tags
}
EOF
cat > data.tf <<'EOF'
resource "aws_db_subnet_group" "main" {
  name       = "${local.prefix}-db"
  subnet_ids = aws_subnet.private[*].id
  tags       = merge(local.tags, { Name = "${local.prefix}-db" })
}

resource "aws_db_instance" "main" {
  identifier             = "${local.prefix}-pg"
  engine                 = "postgres"
  engine_version         = "16.3"
  instance_class         = "db.t4g.micro"
  allocated_storage      = 20
  db_name                = local.cfg.db_name
  username               = local.cfg.db_username
  password               = local.db_password
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.this["database"].arn
  publicly_accessible    = false
  skip_final_snapshot    = true
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  apply_immediately      = true
  tags                   = merge(local.tags, { Name = "${local.prefix}-pg" })

  lifecycle {
    ignore_changes = [password, engine_version]
  }
}

resource "aws_dynamodb_table" "projections" {
  name         = "${local.prefix}-projections"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  attribute {
    name = "PK"
    type = "S"
  }
  attribute {
    name = "SK"
    type = "S"
  }
  attribute {
    name = "GSI1PK"
    type = "S"
  }
  attribute {
    name = "GSI1SK"
    type = "S"
  }

  global_secondary_index {
    name            = "AccountIndex"
    hash_key        = "GSI1PK"
    range_key       = "GSI1SK"
    projection_type = "ALL"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.this["projection"].arn
  }

  tags = merge(local.tags, { Name = "${local.prefix}-projections" })
}

resource "aws_elasticache_subnet_group" "main" {
  name       = "${local.prefix}-cache"
  subnet_ids = aws_subnet.private[*].id
  tags       = local.tags
}

resource "aws_elasticache_replication_group" "main" {
  replication_group_id = "${local.prefix}-valkey"
  description          = "ClearLedger projection cache"
  engine               = "valkey"
  engine_version       = "8.0"
  node_type            = "cache.t4g.micro"
  num_cache_clusters   = 1
  port                 = 6379
  subnet_group_name    = aws_elasticache_subnet_group.main.name
  security_group_ids   = [aws_security_group.valkey.id]
  tags                 = merge(local.tags, { Name = "${local.prefix}-valkey" })
}

resource "aws_s3_bucket" "audit" {
  bucket        = "${local.prefix}-audit-archive"
  force_destroy = true
  tags          = merge(local.tags, { Name = "${local.prefix}-audit-archive" })
}

resource "aws_s3_bucket_versioning" "audit" {
  bucket = aws_s3_bucket.audit.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
  bucket = aws_s3_bucket.audit.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this["audit"].arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "audit" {
  bucket                  = aws_s3_bucket.audit.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_sqs_queue" "dlq" {
  name                      = "${local.prefix}-events-dlq"
  kms_master_key_id         = aws_kms_key.this["messaging"].arn
  message_retention_seconds = 1209600
  tags                      = merge(local.tags, { Name = "${local.prefix}-events-dlq" })
}

resource "aws_sqs_queue" "main" {
  name                       = "${local.prefix}-events"
  kms_master_key_id          = aws_kms_key.this["messaging"].arn
  visibility_timeout_seconds = 3
  receive_wait_time_seconds  = 2
  message_retention_seconds  = 172800
  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq.arn
    maxReceiveCount     = 4
  })
  tags = merge(local.tags, { Name = "${local.prefix}-events" })
}
EOF
cat > cognito.tf <<'EOF'
resource "aws_cognito_user_pool" "main" {
  name = "${local.prefix}-users"
  tags = local.tags
}

resource "aws_cognito_resource_server" "main" {
  identifier   = "clearledger"
  name         = "${local.prefix}-clearledger"
  user_pool_id = aws_cognito_user_pool.main.id

  scope {
    scope_name        = "read"
    scope_description = "Read settlements and ledgers"
  }
  scope {
    scope_name        = "write"
    scope_description = "Initiate settlements and append entries"
  }
  scope {
    scope_name        = "admin"
    scope_description = "Administrative projection rebuilds"
  }
}

resource "aws_cognito_user_pool_client" "this" {
  for_each = toset(["read", "write", "admin"])

  name                                 = "${local.prefix}-${each.key}"
  user_pool_id                         = aws_cognito_user_pool.main.id
  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["client_credentials"]
  allowed_oauth_scopes                 = ["clearledger/${each.key}"]
  supported_identity_providers         = ["COGNITO"]

  depends_on = [aws_cognito_resource_server.main]
}
EOF

cd /workspace/submission/infra
cat > iam.tf <<'EOF'
locals {
  kms_arn = { for k, v in aws_kms_key.this : k => v.arn }

  log_arns = {
    api       = aws_cloudwatch_log_group.api.arn
    projector = aws_cloudwatch_log_group.projector.arn
    relay     = aws_cloudwatch_log_group.relay.arn
    archiver  = aws_cloudwatch_log_group.archiver.arn
  }
  # Log group + the log streams in it.
  log_res = { for k, v in local.log_arns : k => [v, "${v}:*"] }

  queue_arn = aws_sqs_queue.main.arn
  dlq_arn   = aws_sqs_queue.dlq.arn
  all_queues = [local.queue_arn, local.dlq_arn]

  table_arn = aws_dynamodb_table.projections.arn
  table_res = [local.table_arn, "${local.table_arn}/index/AccountIndex"]

  bucket_arn = aws_s3_bucket.audit.arn
  bucket_res = [local.bucket_arn, "${local.bucket_arn}/*"]

  kms_use  = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
  kms_deny = ["kms:Decrypt", "kms:GenerateDataKey"]
  logs_rw  = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]
  logs_w   = ["logs:CreateLogStream", "logs:PutLogEvents"]
  s3_deny  = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
  ddb_all5 = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
  sqs_all3 = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]

  other_logs = {
    for w in keys(local.log_arns) :
    w => flatten([for o in keys(local.log_arns) : local.log_res[o] if o != w])
  }

  trust = {
    for svc in ["ecs-tasks", "lambda", "scheduler"] : svc => jsonencode({
      Version = "2012-10-17"
      Statement = [{
        Effect    = "Allow"
        Principal = { Service = "${svc}.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }]
    })
  }

  policies = {
    ecs_execution = {
      trust = "ecs-tasks"
      statements = [
        { Sid = "AllowOwnLogGroup", Effect = "Allow", Action = local.logs_rw, Resource = local.log_res.api },
        { Sid = "DenyQueues", Effect = "Deny", Action = local.sqs_all3, Resource = local.all_queues },
        { Sid = "DenyProjectionTable", Effect = "Deny", Action = local.ddb_all5, Resource = local.table_res },
        { Sid = "DenyAuditBucket", Effect = "Deny", Action = local.s3_deny, Resource = local.bucket_res },
        { Sid = "DenyAllKmsKeys", Effect = "Deny", Action = local.kms_deny, Resource = values(local.kms_arn) },
        { Sid = "DenyOtherLogGroups", Effect = "Deny", Action = local.logs_w, Resource = local.other_logs.api },
      ]
    }
    ecs_task = {
      trust = "ecs-tasks"
      statements = [
        { Sid = "AllowPublishMainQueue", Effect = "Allow", Action = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"], Resource = [local.queue_arn] },
        { Sid = "AllowReadProjection", Effect = "Allow", Action = ["dynamodb:GetItem", "dynamodb:Query", "dynamodb:DescribeTable"], Resource = local.table_res },
        { Sid = "AllowKms", Effect = "Allow", Action = local.kms_use, Resource = [local.kms_arn.messaging, local.kms_arn.projection] },
        { Sid = "AllowOwnLogGroup", Effect = "Allow", Action = local.logs_rw, Resource = local.log_res.api },
        { Sid = "DenyQueueConsume", Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [local.queue_arn] },
        { Sid = "DenyDlqAccess", Effect = "Deny", Action = local.sqs_all3, Resource = [local.dlq_arn] },
        { Sid = "DenyProjectionMutation", Effect = "Deny", Action = ["dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:DeleteTable"], Resource = local.table_res },
        { Sid = "DenyAuditBucket", Effect = "Deny", Action = local.s3_deny, Resource = local.bucket_res },
        { Sid = "DenyForeignKms", Effect = "Deny", Action = local.kms_deny, Resource = [local.kms_arn.database, local.kms_arn.audit] },
        { Sid = "DenyOtherLogGroups", Effect = "Deny", Action = local.logs_w, Resource = local.other_logs.api },
      ]
    }
    projector = {
      trust = "lambda"
      statements = [
        { Sid = "AllowConsumeMainQueue", Effect = "Allow", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"], Resource = [local.queue_arn] },
        { Sid = "AllowDlqForward", Effect = "Allow", Action = ["sqs:SendMessage"], Resource = [local.dlq_arn] },
        { Sid = "AllowProjectionUpsert", Effect = "Allow", Action = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:Query"], Resource = local.table_res },
        { Sid = "AllowKms", Effect = "Allow", Action = local.kms_use, Resource = [local.kms_arn.messaging, local.kms_arn.projection] },
        { Sid = "AllowOwnLogGroup", Effect = "Allow", Action = local.logs_rw, Resource = local.log_res.projector },
        { Sid = "DenyMainQueueSend", Effect = "Deny", Action = ["sqs:SendMessage"], Resource = [local.queue_arn] },
        { Sid = "DenyDlqConsume", Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [local.dlq_arn] },
        { Sid = "DenyProjectionDelete", Effect = "Deny", Action = ["dynamodb:DeleteItem", "dynamodb:DeleteTable"], Resource = local.table_res },
        { Sid = "DenyAuditBucket", Effect = "Deny", Action = local.s3_deny, Resource = local.bucket_res },
        { Sid = "DenyForeignKms", Effect = "Deny", Action = local.kms_deny, Resource = [local.kms_arn.database, local.kms_arn.audit] },
        { Sid = "DenyOtherLogGroups", Effect = "Deny", Action = local.logs_w, Resource = local.other_logs.projector },
      ]
    }
    relay = {
      trust = "lambda"
      statements = [
        { Sid = "AllowPublishMainQueue", Effect = "Allow", Action = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"], Resource = [local.queue_arn] },
        { Sid = "AllowKms", Effect = "Allow", Action = local.kms_use, Resource = [local.kms_arn.messaging, local.kms_arn.database] },
        { Sid = "AllowOwnLogGroup", Effect = "Allow", Action = local.logs_rw, Resource = local.log_res.relay },
        { Sid = "DenyQueueConsume", Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [local.queue_arn] },
        { Sid = "DenyDlqAccess", Effect = "Deny", Action = local.sqs_all3, Resource = [local.dlq_arn] },
        { Sid = "DenyProjectionTable", Effect = "Deny", Action = local.ddb_all5, Resource = local.table_res },
        { Sid = "DenyAuditBucket", Effect = "Deny", Action = local.s3_deny, Resource = local.bucket_res },
        { Sid = "DenyForeignKms", Effect = "Deny", Action = local.kms_deny, Resource = [local.kms_arn.projection, local.kms_arn.audit] },
        { Sid = "DenyOtherLogGroups", Effect = "Deny", Action = local.logs_w, Resource = local.other_logs.relay },
      ]
    }
    archiver = {
      trust = "lambda"
      statements = [
        { Sid = "AllowAuditObjects", Effect = "Allow", Action = ["s3:PutObject", "s3:GetObject", "s3:AbortMultipartUpload"], Resource = ["${local.bucket_arn}/ledger-audit/*"] },
        { Sid = "AllowAuditBucketMetadata", Effect = "Allow", Action = ["s3:ListBucket", "s3:GetBucketLocation"], Resource = [local.bucket_arn] },
        { Sid = "AllowKms", Effect = "Allow", Action = local.kms_use, Resource = [local.kms_arn.audit, local.kms_arn.database] },
        { Sid = "AllowOwnLogGroup", Effect = "Allow", Action = local.logs_rw, Resource = local.log_res.archiver },
        { Sid = "DenyAuditDelete", Effect = "Deny", Action = ["s3:DeleteObject", "s3:DeleteObjectVersion"], Resource = local.bucket_res },
        { Sid = "DenyQueues", Effect = "Deny", Action = local.sqs_all3, Resource = local.all_queues },
        { Sid = "DenyProjectionTable", Effect = "Deny", Action = local.ddb_all5, Resource = local.table_res },
        { Sid = "DenyForeignKms", Effect = "Deny", Action = local.kms_deny, Resource = [local.kms_arn.messaging, local.kms_arn.projection] },
        { Sid = "DenyOtherLogGroups", Effect = "Deny", Action = local.logs_w, Resource = local.other_logs.archiver },
      ]
    }
    scheduler = {
      trust = "scheduler"
      statements = [
        { Sid = "AllowInvokeWorkers", Effect = "Allow", Action = ["lambda:InvokeFunction"], Resource = [aws_lambda_function.outbox_relay.arn, aws_lambda_function.audit_archiver.arn] },
        { Sid = "DenyInvokeProjector", Effect = "Deny", Action = ["lambda:InvokeFunction"], Resource = [aws_lambda_function.projector.arn] },
        { Sid = "DenyQueues", Effect = "Deny", Action = local.sqs_all3, Resource = local.all_queues },
        { Sid = "DenyProjectionTable", Effect = "Deny", Action = local.ddb_all5, Resource = local.table_res },
        { Sid = "DenyAuditBucket", Effect = "Deny", Action = local.s3_deny, Resource = local.bucket_res },
        { Sid = "DenyAllKmsKeys", Effect = "Deny", Action = local.kms_deny, Resource = values(local.kms_arn) },
        { Sid = "DenyAllLogGroups", Effect = "Deny", Action = local.logs_w, Resource = flatten(values(local.log_res)) },
      ]
    }
  }
}

resource "aws_iam_role" "this" {
  for_each           = local.policies
  name               = "${local.prefix}-${replace(each.key, "_", "-")}"
  assume_role_policy = local.trust[each.value.trust]
  tags               = merge(local.tags, { Name = "${local.prefix}-${replace(each.key, "_", "-")}" })
}

resource "aws_iam_role_policy" "this" {
  for_each = local.policies
  name     = "${local.prefix}-${replace(each.key, "_", "-")}-policy"
  role     = aws_iam_role.this[each.key].id
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = each.value.statements
  })
}
EOF
cat > compute.tf <<'EOF'
locals {
  db_url     = "postgres://${local.cfg.db_username}:${local.db_password}@${aws_db_instance.main.address}:${aws_db_instance.main.port}/${local.cfg.db_name}"
  valkey_url = "redis://${aws_elasticache_replication_group.main.primary_endpoint_address}:${aws_elasticache_replication_group.main.port}"
  issuer_url = "${local.endpoint}/${aws_cognito_user_pool.main.id}"
  audiences  = join(",", [for k in ["read", "write", "admin"] : aws_cognito_user_pool_client.this[k].id])

  aws_env = {
    AWS_REGION            = local.region
    AWS_DEFAULT_REGION    = local.region
    AWS_ACCESS_KEY_ID     = "test"
    AWS_SECRET_ACCESS_KEY = "test"
    AWS_ENDPOINT_URL      = local.endpoint
  }
}

# ---------------------------------------------------------------- Lambda workers

resource "aws_lambda_function" "projector" {
  function_name = "${local.prefix}-projector"
  package_type  = "Image"
  image_uri     = local.cfg.projector_image
  role          = aws_iam_role.this["projector"].arn
  timeout       = 3
  memory_size   = 256
  tags          = merge(local.tags, { Name = "${local.prefix}-projector" })

  environment {
    variables = merge(local.aws_env, {
      PROJECTION_TABLE     = aws_dynamodb_table.projections.name
      VALKEY_URL           = local.valkey_url
      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.projector.name
    })
  }

  depends_on = [aws_iam_role_policy.this]
}

resource "aws_lambda_function" "outbox_relay" {
  function_name = "${local.prefix}-outbox-relay"
  package_type  = "Image"
  image_uri     = local.cfg.relay_image
  role          = aws_iam_role.this["relay"].arn
  timeout       = 60
  memory_size   = 256
  tags          = merge(local.tags, { Name = "${local.prefix}-outbox-relay" })

  environment {
    variables = merge(local.aws_env, {
      DATABASE_URL         = local.db_url
      SQS_QUEUE_URL        = aws_sqs_queue.main.url
      OUTBOX_BATCH_SIZE    = "50"
      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.relay.name
    })
  }

  depends_on = [aws_iam_role_policy.this]
}

resource "aws_lambda_function" "audit_archiver" {
  function_name = "${local.prefix}-audit-archiver"
  package_type  = "Image"
  image_uri     = local.cfg.archiver_image
  role          = aws_iam_role.this["archiver"].arn
  timeout       = 120
  memory_size   = 256
  tags          = merge(local.tags, { Name = "${local.prefix}-audit-archiver" })

  environment {
    variables = merge(local.aws_env, {
      DATABASE_URL         = local.db_url
      AUDIT_BUCKET         = aws_s3_bucket.audit.bucket
      AUDIT_PREFIX         = "ledger-audit/"
      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.archiver.name
    })
  }

  depends_on = [aws_iam_role_policy.this]
}

resource "aws_lambda_event_source_mapping" "projector" {
  event_source_arn                   = aws_sqs_queue.main.arn
  function_name                      = aws_lambda_function.projector.arn
  enabled                            = true
  batch_size                         = 5
  maximum_batching_window_in_seconds = 0
  function_response_types            = ["ReportBatchItemFailures"]
}

# ---------------------------------------------------------------- Schedules

resource "aws_scheduler_schedule" "outbox" {
  name                         = "${local.prefix}-outbox-relay"
  schedule_expression          = "rate(1 minute)"
  state                        = "ENABLED"
  flexible_time_window {
    mode = "OFF"
  }
  target {
    arn      = aws_lambda_function.outbox_relay.arn
    role_arn = aws_iam_role.this["scheduler"].arn
  }
}

resource "aws_scheduler_schedule" "archive" {
  name                = "${local.prefix}-audit-archiver"
  schedule_expression = "rate(5 minutes)"
  state               = "ENABLED"
  flexible_time_window {
    mode = "OFF"
  }
  target {
    arn      = aws_lambda_function.audit_archiver.arn
    role_arn = aws_iam_role.this["scheduler"].arn
  }
}

# ---------------------------------------------------------------- ALB

resource "aws_lb" "main" {
  name               = "${local.prefix}-alb"
  load_balancer_type = "application"
  internal           = false
  subnets            = aws_subnet.public[*].id
  security_groups    = [aws_security_group.alb.id]
  tags               = merge(local.tags, { Name = "${local.prefix}-alb" })
}

resource "aws_lb_target_group" "api" {
  name                 = "${local.prefix}-api"
  port                 = 8080
  protocol             = "HTTP"
  target_type          = "ip"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 5

  health_check {
    path                = "/health/ready"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 10
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = merge(local.tags, { Name = "${local.prefix}-api" })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.api.arn
  }

  tags = local.tags
}

# ---------------------------------------------------------------- ECS

resource "aws_ecs_cluster" "main" {
  name = "${local.prefix}-cluster"
  setting {
    name  = "containerInsights"
    value = "enabled"
  }
  tags = merge(local.tags, { Name = "${local.prefix}-cluster" })
}

resource "aws_ecs_task_definition" "api" {
  family                   = "${local.prefix}-api"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.this["ecs_execution"].arn
  task_role_arn            = aws_iam_role.this["ecs_task"].arn
  tags                     = merge(local.tags, { Name = "${local.prefix}-api" })

  container_definitions = jsonencode([
    {
      name         = "api"
      image        = local.cfg.api_image
      essential    = true
      portMappings = [{ containerPort = 8080, hostPort = 8080, protocol = "tcp" }]
      environment = [for k, v in merge(local.aws_env, {
        PORT                 = "8080"
        DATABASE_URL         = local.db_url
        SQS_QUEUE_URL        = aws_sqs_queue.main.url
        PROJECTION_TABLE     = aws_dynamodb_table.projections.name
        VALKEY_URL           = local.valkey_url
        CACHE_TTL_SECONDS    = "90"
        AUTH_ISSUER          = local.issuer_url
        AUTH_AUDIENCES       = local.audiences
        AUTH_JWKS_URL        = "${local.issuer_url}/.well-known/jwks.json"
        CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.api.name
      }) : { name = k, value = v }]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.api.name
          "awslogs-region"        = local.region
          "awslogs-stream-prefix" = "api"
        }
      }
    }
  ])
}

resource "aws_ecs_service" "api" {
  name            = "${local.prefix}-api"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.api.arn
  desired_count   = 2
  launch_type     = "FARGATE"

  health_check_grace_period_seconds = 30

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.api.arn
    container_name   = "api"
    container_port   = 8080
  }

  tags       = merge(local.tags, { Name = "${local.prefix}-api" })
  depends_on = [aws_lb_listener.http, aws_iam_role_policy.this]
}
EOF
